    var existeNomina = <?php echo $existe_nomina ? 'true' : 'false'; ?>;
    var tipoNominaTexto = '<?php echo $tipos_nomina[$tipo_nomina_activa]['nombre']; ?>';
    var periodoTexto = '<?php echo $nombre_mes . ' ' . $anio; ?>';
    
    if (!existeNomina) {
