    }).join('');
    
    $('#selectedExtraList').html(html || '<em class="text-white-50"><i class="fas fa-users me-1"></i>Seleccione trabajadores de la lista izquierda</em>');
    
    if (focusId) {
        setTimeout(function() {
            var $input = $('#selectedExtraList').find(`.horas-input[data-id="${focusId}"]`);
            if ($input.length) {
                $input.focus().select();
